def _handle_dict(target, spec, scope):
    if not isinstance(target, dict):
        raise TypeMatchError(type(target), dict)
    required_keys = []
    optional_keys = []
    for key in spec:
        if type(key) is Optional:
            optional_keys.append(key)
        elif type(key) is Required:
            required_keys.append(key)
        elif _precedence(key) == 0:
            required_keys.append(key)
        else:
            optional_keys.append(key)
    result = {}
    unmatched_required = list(required_keys)
    for target_key, target_val in target.items():
        matched = False
        for spec_key in required_keys + optional_keys:
            raw_key = spec_key.key if type(spec_key) in (Required, Optional) else spec_key
            try:
                scope[glom](target_key, raw_key, scope)
            except GlomError:
                continue
            result[target_key] = scope[glom](target_val, spec[spec_key], scope)
            if spec_key in unmatched_required:
                unmatched_required.remove(spec_key)
            matched = True
            break
        if not matched:
            raise MatchError("key {0!r} didn't match any of {1!r}", target_key, list(spec.keys()))
    if unmatched_required:
        raise MatchError("target missing expected keys {0}", unmatched_required[0])
    for key in optional_keys:
        if type(key) is Optional and key.default is not _MISSING:
            raw_key = key.key
            if raw_key not in result:
                result[raw_key] = key.default
    return result


def _glom_match(target, spec, scope):
    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(type(target), spec)
        return target
    if hasattr(spec, 'glomit'):
        return scope[glom](target, spec, scope)
    if isinstance(spec, dict):
        return _handle_dict(target, spec, scope)
    if isinstance(spec, (list, tuple, set, frozenset)):
        if not isinstance(target, type(spec)):
            raise TypeMatchError(type(target), type(spec))
        if type(spec) in (set, frozenset):
            if len(spec) == 0:
                if len(target) != 0:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if len(spec) != 1:
                raise ValueError("set/frozenset specs must have exactly one element")
            (item_spec,) = spec
            for item in target:
                scope[glom](item, item_spec, scope)
            return target
        if type(spec) is list:
            if len(spec) == 0:
                if len(target) != 0:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if len(spec) != 1:
                raise ValueError("list specs must have exactly one element")
            item_spec = spec[0]
            result = []
            for item in target:
                result.append(scope[glom](item, item_spec, scope))
            return result
        if type(spec) is tuple:
            if len(spec) != len(target):
                raise MatchError("{0!r} does not match {1!r}", target, spec)
            result = []
            for item, item_spec in zip(target, spec):
                result.append(scope[glom](item, item_spec, scope))
            return type(target)(result)
    if target != spec:
        raise MatchError("{0!r} does not match {1!r}", target, spec)
    return target
